/**
 * Ranking probability for PROVEN path — independent modelProb when available.
 *
 * Law (v5.2.1):
 *   When independent estimators yield a finite trueProb in (0,1), use that
 *   (or blend with confidence) as rankingP — including PASS. Edge SPEAK/LEAN
 *   is the glass-box claim; ranking needs P(side) even when we do not claim edge.
 *   Overpriced favorites (trueProb < conf) must demote ranking or RES stays ~0.
 *
 *   NEVER use rawEdge / shrunkEdge / edgeScore as ranking p.
 *
 * Does NOT lower floors, flip AUTO_PUBLISH, or apply calibration maps.
 */

import type { IndependentEdgeSummary } from "@sports/types";

export type RankingProbSource =
  | "confidence"
  | "independent_trueProb"
  | "blend_indep_conf";

export type RankingProbResult = {
  /** Probability in (0, 1) used for sort / selective / bake-off. */
  readonly rankingP: number;
  /** 0–100 scale of rankingP (generation sort key). */
  readonly rankingScore: number;
  readonly source: RankingProbSource;
  /** True when independents drove the ranking path (priced into ranking). */
  readonly priced: boolean;
};

function clamp01(p: number): number {
  return Math.min(1 - 1e-6, Math.max(1e-6, p));
}

/**
 * Derive ranking probability from heuristic confidence + optional independent edge.
 *
 * Finite trueProb → blend (default) or pure independent — even on PASS.
 * Missing / non-finite trueProb → confidence only.
 */
export function deriveRankingProbability(
  confidence: number,
  independentEdge: IndependentEdgeSummary | null | undefined,
  options?: {
    /** Weight on independent trueProb when blending (0–1). Default 0.7 (v5.2.1). */
    readonly independentWeight?: number;
    /** Prefer pure trueProb over blend when SPEAK. Default false. */
    readonly pureOnSpeak?: boolean;
    /**
     * When true (default), use trueProb for ranking even if decision is PASS.
     * SPEAK/LEAN still control glass-box edge claim; ranking needs the model P.
     */
    readonly rankOnAnyTrueProb?: boolean;
  },
): RankingProbResult {
  const confP = clamp01(
    Number.isFinite(confidence) ? confidence / 100 : 0.5,
  );

  const ie = independentEdge ?? null;
  const trueProb = ie?.trueProb;
  const decision = ie?.decision;
  const hasModelP =
    trueProb != null &&
    Number.isFinite(trueProb) &&
    trueProb > 0 &&
    trueProb < 1;

  // Legacy gate (rankOnAnyTrueProb === false): only SPEAK|LEAN.
  const rankOnAny = options?.rankOnAnyTrueProb !== false;
  const decisionOk =
    rankOnAny || decision === "SPEAK" || decision === "LEAN";
  const canPrice = ie != null && hasModelP && decisionOk;

  if (!canPrice) {
    return {
      rankingP: confP,
      rankingScore: Math.round(confP * 100),
      source: "confidence",
      priced: false,
    };
  }

  const w = Math.min(1, Math.max(0, options?.independentWeight ?? 0.7));
  const pure =
    options?.pureOnSpeak === true &&
    (decision === "SPEAK" || rankOnAny);
  let rankingP: number;
  let source: RankingProbSource;
  if (pure || w >= 1 - 1e-12) {
    rankingP = clamp01(trueProb as number);
    source = "independent_trueProb";
  } else if (w <= 1e-12) {
    rankingP = confP;
    source = "confidence";
  } else {
    rankingP = clamp01((1 - w) * confP + w * (trueProb as number));
    source = "blend_indep_conf";
  }

  return {
    rankingP,
    rankingScore: Math.round(rankingP * 100),
    source,
    priced: source !== "confidence",
  };
}

/**
 * Season standings win% → independent ML fair value (Bradley–Terry / logit).
 *
 * Pure math. Never invents win%. Null when either side missing or sample thin.
 * Source label: "mlb_standings" (or caller override) — model-fair only, not a book.
 *
 *   logit(p_home) = logit(wpct_h) − logit(wpct_a) + hfa_logit
 *   p_home = sigmoid(logit)
 *
 * HFA default ~0.18 logit (~55% for two .500 teams) — baseball home edge.
 */

import type { IndependentMarketFairValue } from "@sports/types";

const EPS = 1e-6;

function clipProb(p: number): number {
  return Math.min(1 - EPS, Math.max(EPS, p));
}

function logit(p: number): number {
  const x = clipProb(p);
  return Math.log(x / (1 - x));
}

function sigmoid(z: number): number {
  if (z >= 0) {
    const e = Math.exp(-z);
    return 1 / (1 + e);
  }
  const e = Math.exp(z);
  return e / (1 + e);
}

export type StandingsStrengthInput = {
  readonly homeWinPct: number;
  readonly awayWinPct: number;
  /** Minimum games played (wins+losses) per side when available. */
  readonly homeGames?: number;
  readonly awayGames?: number;
  /** Default 0.18 (≈ +4.5% for equal teams). */
  readonly hfaLogit?: number;
  /** Soft-fail when either side has fewer games (default 20). */
  readonly minGames?: number;
  readonly source?: string;
};

/**
 * Convert two season win rates into home/away win probs.
 * Returns null on non-finite, out-of-range, or thin-sample inputs.
 */
export function standingsWinPctToWinProbs(
  input: StandingsStrengthInput,
): { readonly pHome: number; readonly pAway: number; readonly marginLogit: number } | null {
  const { homeWinPct, awayWinPct } = input;
  if (
    !Number.isFinite(homeWinPct) ||
    !Number.isFinite(awayWinPct) ||
    homeWinPct <= 0 ||
    homeWinPct >= 1 ||
    awayWinPct <= 0 ||
    awayWinPct >= 1
  ) {
    return null;
  }
  const minGames = input.minGames ?? 20;
  if (
    (input.homeGames != null && input.homeGames < minGames) ||
    (input.awayGames != null && input.awayGames < minGames)
  ) {
    return null;
  }
  const hfa =
    input.hfaLogit != null && Number.isFinite(input.hfaLogit) ? input.hfaLogit : 0.18;
  // Discrimination scale: mild stretch so strong/weak teams separate (RES lever).
  // 1.1 — was 1.15; pair with softer blend stretch for Brier/ECE discipline.
  const DISCRIM = 1.1;
  const marginLogit = (logit(homeWinPct) - logit(awayWinPct) + hfa) * DISCRIM;
  const pHome = clipProb(sigmoid(marginLogit));
  return { pHome, pAway: clipProb(1 - pHome), marginLogit };
}

export function standingsWinPctToIndependentFairValue(
  input: StandingsStrengthInput,
  options?: { readonly now?: () => Date },
): IndependentMarketFairValue | null {
  const r = standingsWinPctToWinProbs(input);
  if (!r) return null;
  return {
    source: input.source ?? "mlb_standings",
    homeFairProb: r.pHome,
    awayFairProb: r.pAway,
    capturedAt: (options?.now ?? (() => new Date()))().toISOString(),
  };
}

/**
 * Market consensus q — and why Kaggle 3rd-place March Mania is not an edge.
 *
 * kevin1000's 2026 Mania writeup (Brier 0.116, #3/3485) won by publishing
 *   published = (1 − α) · p_LR + α · q_market
 * with α = 0.90 (men's R1) / 0.75 (women's R1). That is a **forecast**
 * product: markets already price injuries/travel, so Brier vs the outcome
 * drops. Residual edge vs the same market is
 *   (published − q) = (1 − α)(p − q)
 * so α = 0.90 leaves 10% of the independent gap. GSE fires on e = p − q,
 * never on a re-anchored published probability.
 *
 * What we do take, closed-form:
 *  1. Bradley-Terry pairwise from championship/futures strengths
 *     P(A beats B) = s_A / (s_A + s_B) when no game-specific board exists.
 *  2. Logit-weighted consensus of labeled q sources (their 60% Vegas /
 *     40% BPI mix) — as q, never as p.
 *  3. The residual-edge identity above, as a glass-box diagnostic.
 *
 * ESPN HTML scrape and sportsbook HTML scrape stay out. Callers supply
 * already-cleared probabilities.
 */

export interface LabeledQ {
  readonly id: string;
  readonly q: number;
  readonly weight: number;
}

export interface ConsensusQ {
  readonly q: number;
  readonly sourceIds: readonly string[];
  readonly n: number;
}

export interface ReanchorResidual {
  readonly independentEdge: number;
  readonly publishedP: number;
  readonly residualEdge: number;
  readonly marketWeight: number;
}

function assertUnit(p: number, label: string): void {
  if (!Number.isFinite(p) || p <= 0 || p >= 1) {
    throw new RangeError(`${label} must be in (0, 1) (got ${p})`);
  }
}

function logit(p: number): number {
  const pc = Math.min(1 - 1e-9, Math.max(1e-9, p));
  return Math.log(pc / (1 - pc));
}

function sigmoid(z: number): number {
  if (z >= 0) return 1 / (1 + Math.exp(-z));
  const e = Math.exp(z);
  return e / (1 + e);
}

/**
 * Bradley-Terry pairwise win probability from positive strengths
 * (championship implied probs, Elo-as-strength, etc.).
 */
export function bradleyTerryPair(strengthA: number, strengthB: number): number {
  if (!Number.isFinite(strengthA) || !Number.isFinite(strengthB) || strengthA <= 0 || strengthB <= 0) {
    throw new RangeError(
      `bradleyTerryPair: strengths must be finite and > 0 (got ${strengthA}, ${strengthB})`,
    );
  }
  return strengthA / (strengthA + strengthB);
}

/**
 * Logit-weighted consensus of labeled market/model quotes. Fail closed
 * (null) when no positive-weight finite q remains. This is q, not p.
 */
export function consensusMarketQ(sources: readonly LabeledQ[]): ConsensusQ | null {
  if (sources.length === 0) return null;
  let num = 0;
  let den = 0;
  const ids: string[] = [];
  for (const s of sources) {
    if (typeof s.id !== "string" || s.id.length === 0) {
      throw new RangeError("consensusMarketQ: id must be a non-empty string");
    }
    if (!Number.isFinite(s.weight) || s.weight < 0) {
      throw new RangeError(`consensusMarketQ: weight must be finite and >= 0 (got ${s.weight})`);
    }
    if (s.weight === 0) continue;
    assertUnit(s.q, `consensusMarketQ[${s.id}].q`);
    num += s.weight * logit(s.q);
    den += s.weight;
    ids.push(s.id);
  }
  if (!(den > 0) || ids.length === 0) return null;
  return { q: sigmoid(num / den), sourceIds: ids, n: ids.length };
}

/**
 * Identity: blending p toward q with weight α shrinks edge by (1 − α).
 * The Mania 3rd-place R1 men's α = 0.90 → residual = 0.10 × (p − q).
 */
export function marketReanchorResidual(p: number, q: number, marketWeight: number): ReanchorResidual {
  assertUnit(p, "p");
  assertUnit(q, "q");
  if (!Number.isFinite(marketWeight) || marketWeight < 0 || marketWeight > 1) {
    throw new RangeError(`marketWeight must be in [0, 1] (got ${marketWeight})`);
  }
  const independentEdge = p - q;
  const publishedP = (1 - marketWeight) * p + marketWeight * q;
  return {
    independentEdge,
    publishedP,
    residualEdge: publishedP - q,
    marketWeight,
  };
}

/**
 * Platform Readiness Gates
 *
 * Single source of truth for "can this system do X right now?"
 * Used across workers, API routes, and content generation to enforce
 * consistent operational boundaries based on PlatformConfig.
 *
 * Usage:
 *   import { getReadinessGates, bootstrapGateResponse } from "@sports/prediction-engine";
 *
 *   const gates = getReadinessGates();
 *   if (!gates.canExposePublicPicks) {
 *     return NextResponse.json(bootstrapGateResponse("Public picks"), { status: 503 });
 *   }
 */

import { getPlatformConfig } from "./platform-config.js";
import type { PlatformConfig, ConfidenceDisplayMode } from "./platform-config.js";

export interface ReadinessGates {
  /** Scoring is always permitted — the engine never goes offline. */
  readonly canScore: true;

  /**
   * Picks can always be persisted for internal validation and settlement.
   * The isBootstrap field distinguishes canonical from bootstrap-era picks.
   */
  readonly canPersistPicks: true;

  /**
   * When false: new TeamGameLog entries and picks are written with isBootstrap=true.
   * They remain in the DB but do not count toward canonical performance history.
   */
  readonly canPersistCanonicalHistory: boolean;

  /**
   * When false: ATS form, H2H form, and venue splits produce score=0 in the
   * prediction engine (context fields are set to null before scoring).
   * Only non-bootstrap TeamGameLog entries are used when this is true.
   */
  readonly canUseDerivedHistory: boolean;

  /**
   * When false: /api/picks and /api/picks/daily-slate return 503.
   * Picks are still generated and stored for admin review.
   */
  readonly canExposePublicPicks: boolean;

  /**
   * When false: isFeatured is always set to false on new picks regardless of grade.
   */
  readonly canPromoteFeaturedPicks: boolean;

  /**
   * When false: content-publishing worker skips all generation.
   */
  readonly canPublishContent: boolean;

  /**
   * When false: /api/performance returns 503.
   * Prevents bootstrap-era win rates from appearing as production metrics.
   */
  readonly canExposePerformanceStats: boolean;

  /**
   * True when canonicalHistoryEnabled is false.
   * Callers can use this to add [BOOTSTRAP] warnings in admin UI or logs.
   */
  readonly isBootstrapMode: boolean;

  /** How confidence should be presented to users at this maturity level. */
  readonly confidenceDisplayMode: ConfidenceDisplayMode;

  /** Minimum dataQualityScore for a game's TeamGameLog entry to be written. */
  readonly minDataQualityForGameLog: number;

  /**
   * When true: settled canonical PickSignalSnapshots are marked eligibleForLearning=true.
   * This gates DATA COLLECTION for outcome-anchored calibration only.
   * It does NOT automatically adjust scoring weights or confidence values.
   *
   * The model may ONLY learn from:
   *   - Real settlement results (WIN/LOSS/PUSH from actual game outcomes)
   *   - Signal state recorded at prediction time (bookmaker count, line movement, etc.)
   *   - External source conditions (bookmaker market depth, coverage)
   *
   * The model MUST NOT learn from:
   *   - Its own prior confidence scores without outcome validation
   *   - Its own prior reasoning text
   *   - Its own prior pick grades in isolation from real outcomes
   *   - Bootstrap-era snapshots (these are excluded by isBootstrap=false filter)
   */
  readonly canLearnFromOutcomes: boolean;

  /**
   * When true: the isotonic calibrator (calibration-apply.ts) is active and
   * confidence scores are mapped to calibrated win probabilities.
   *
   * Defaults to false via CALIBRATION_ADJUSTMENTS_ENABLED env var.
   * Activation requires completing the audited MODEL_VERSION sequence in
   * docs/path-to-70.md §7 — never set this without that audit trail.
   */
  readonly canApplyCalibrationAdjustments: boolean;

  /** Minimum settled canonical picks needed for learning data to be meaningful. */
  readonly minSettledPicksForLearning: number;

  /**
   * Stale-data kill switch for the public picks surface.
   *
   * When true: public read paths (/api/picks, board loaders) must suppress the
   * picks surface — rendering the same "collecting"/empty state they already use
   * — whenever the latest successful ingestion run is classified "stale" by the
   * shared Refresh SLA. This is the read-boundary enforcement of CLAUDE.md rule #5
   * ("no stale data"), letting canExposePublicPicks be lifted safely.
   *
   * Defaults to false via FORCE_NO_BET_IF_STALE — ships dark, no behavior change
   * until explicitly enabled. The gate itself performs NO I/O; consumers own the
   * freshness query + classifyRefreshFreshness call.
   */
  readonly forceNoBetIfStale: boolean;

  /** The underlying config for callers that need specific values. */
  readonly config: PlatformConfig;
}

export function getReadinessGates(): ReadinessGates {
  const config = getPlatformConfig();
  return {
    canScore:                        true,
    canPersistPicks:                 true,
    canPersistCanonicalHistory:      config.canonicalHistoryEnabled,
    canUseDerivedHistory:            config.derivedModelHistoryEnabled,
    canExposePublicPicks:            config.publicPicksEnabled,
    canPromoteFeaturedPicks:         config.featuredPickPromotionEnabled,
    canPublishContent:               config.publicBlogEnabled,
    canExposePerformanceStats:       config.performanceStatsEnabled,
    isBootstrapMode:                 !config.canonicalHistoryEnabled,
    confidenceDisplayMode:           config.confidenceDisplayMode,
    minDataQualityForGameLog:        config.minDataQualityForGameLog,
    canLearnFromOutcomes:            config.outcomeLearningEnabled,
    canApplyCalibrationAdjustments:  config.calibrationAdjustmentsEnabled,
    minSettledPicksForLearning:      config.minSettledPicksForLearning,
    forceNoBetIfStale:               config.forceNoBetIfStale,
    config,
  };
}

/**
 * Returns a structured 503 error body for routes blocked by readiness gates.
 * Pair with `{ status: 503 }` in the route handler.
 *
 * Honesty: do NOT claim "bootstrap mode" when bootstrap is off and only a
 * feature flag (e.g. PUBLIC_PICKS_ENABLED) is closed. Live prod previously
 * reported isBootstrapMode=false while /api/picks said bootstrapMode:true.
 */
export function bootstrapGateResponse(featureName: string): {
  error: string;
  /** True only when CANONICAL_HISTORY is still off (true bootstrap). */
  bootstrapMode: boolean;
  /** Distinguishes history-bootstrap from a deliberate feature gate. */
  reason: "bootstrap" | "feature_gate";
  hint: string;
} {
  const gates = getReadinessGates();
  if (gates.isBootstrapMode) {
    return {
      error: `${featureName} is disabled in bootstrap mode.`,
      bootstrapMode: true,
      reason: "bootstrap",
      hint: "Set the appropriate environment flag to enable this feature. See .env.example for the bootstrap progression guide.",
    };
  }
  return {
    error: `${featureName} is disabled by feature gate.`,
    bootstrapMode: false,
    reason: "feature_gate",
    hint:
      "Founder-gated closed (e.g. PUBLIC_PICKS_ENABLED / PERFORMANCE_STATS_ENABLED). Not bootstrap history mode — see /api/ops/public-surface-truth gates.",
  };
}

/**
 * Calibration maps — parametric recalibrators (Platt, Beta) and an honest,
 * cross-validated selector across calibrator families. R&D, NOT wired into live
 * scoring (same dark posture as probability-calibration.ts / calibration-apply.ts).
 *
 * WHY THIS EXISTS (the gap it fills):
 *   probability-calibration.ts ships ONE calibrator — isotonic (PAVA) — and
 *   calibration-apply.ts's buildCalibrator picks it by fiat, only checking that it
 *   beats the raw ECE on the SAME sample it was fit on (an in-sample check that can
 *   flatter an overfit map). Isotonic is non-parametric and is known to OVERFIT at
 *   small n; a smooth parametric map (Platt, Beta) is often better when settled
 *   picks are few — exactly GSE's pre-launch regime. This module adds those two
 *   maps AND a k-fold, out-of-sample ECE selection so "which calibrator" becomes a
 *   measured decision (winner on held-out ECE), not a default.
 *
 * All deterministic: the fold shuffle is seeded (mulberry32); the map fits use
 * Newton/IRLS with no randomness. No I/O. Operates on the same CalibrationSample
 * {p in [0,1], y in {0,1}} type as the rest of the calibration toolkit.
 *
 * Sources: Platt (1999) probabilistic outputs; Kull, Silva Filho & Flach (2017)
 * "Beta calibration". Both re-derived here from first principles (logistic fit),
 * not copied — the only constants are the Platt target-smoothing counts, which are
 * Platt's exact prescription and are sourced in-line.
 */

import {
  isotonicCalibration,
  type CalibrationSample,
} from "./probability-calibration.js";

const EPS = 1e-6;

function clamp01(x: number): number {
  return Math.max(0, Math.min(1, x));
}
function clampUnit(p: number): number {
  return Math.min(1 - EPS, Math.max(EPS, p));
}
function round(value: number, digits = 6): number {
  const s = 10 ** digits;
  return Math.round(value * s) / s;
}
function sigmoid(z: number): number {
  // Numerically stable.
  if (z >= 0) {
    const e = Math.exp(-z);
    return 1 / (1 + e);
  }
  const e = Math.exp(z);
  return e / (1 + e);
}
function logit(p: number): number {
  const c = clampUnit(p);
  return Math.log(c / (1 - c));
}

/** Deterministic PRNG (mulberry32) — matches the package's other seeded modules. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Seeded Fisher–Yates permutation of [0..n). */
function seededPermutation(n: number, seed: number): number[] {
  const idx = Array.from({ length: n }, (_, i) => i);
  const rand = mulberry32(seed);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    const tmp = idx[i]!;
    idx[i] = idx[j]!;
    idx[j] = tmp;
  }
  return idx;
}

// ============================================================
// Small dense linear solver (Gaussian elimination, partial pivot)
// ============================================================

/** Solve A x = b for small square A (d up to a handful). Returns null if singular. */
function solveLinear(A: readonly (readonly number[])[], b: readonly number[]): number[] | null {
  const d = b.length;
  // Augmented matrix copy.
  const m: number[][] = A.map((row, i) => [...row, b[i]!]);
  for (let col = 0; col < d; col++) {
    // Partial pivot.
    let pivot = col;
    let best = Math.abs(m[col]![col]!);
    for (let r = col + 1; r < d; r++) {
      const v = Math.abs(m[r]![col]!);
      if (v > best) {
        best = v;
        pivot = r;
      }
    }
    if (best < 1e-14) return null; // singular
    if (pivot !== col) {
      const tmp = m[col]!;
      m[col] = m[pivot]!;
      m[pivot] = tmp;
    }
    const pivRow = m[col]!;
    const pivVal = pivRow[col]!;
    for (let r = 0; r < d; r++) {
      if (r === col) continue;
      const factor = m[r]![col]! / pivVal;
      if (factor === 0) continue;
      const row = m[r]!;
      for (let c = col; c <= d; c++) row[c] = row[c]! - factor * pivRow[c]!;
    }
  }
  const x = new Array<number>(d);
  for (let i = 0; i < d; i++) x[i] = m[i]![d]! / m[i]![i]!;
  return x;
}

// ============================================================
// Generic ridge-regularized logistic regression (Newton / IRLS)
// ============================================================

/**
 * Fit weights w minimizing regularized cross-entropy for design rows `X` and
 * soft targets `t` in [0,1]. Ridge (lambda) on all but the last (intercept)
 * coefficient stabilizes fits under separation. Deterministic; no RNG.
 *
 * REFUSES non-convergence: on (near-)separated data with hard 0/1 targets the
 * optimum is at infinity — without this guard the loop exhausts maxIter and
 * hands back divergent garbage-magnitude weights with no signal (found by
 * hostile review: a one-outlier separated fixture returned coefficients of
 * magnitude ~1e7 as a "successful" fit). Steps are damped to a max-norm of
 * MAX_STEP per iteration so recoverable fits still converge; if the final
 * iteration's step is still above CONVERGED_TOL, the fit did not converge and
 * we return null — an honest refusal instead of a fabricated map.
 */
function fitLogisticIRLS(
  X: readonly (readonly number[])[],
  t: readonly number[],
  lambda = 1e-6,
  maxIter = 100,
  tol = 1e-9,
): number[] | null {
  const n = X.length;
  if (n === 0) return null;
  const MAX_STEP = 10; // per-iteration max |step| component (damping, not a bound on w)
  const CONVERGED_TOL = 1e-4; // a final step larger than this = did not converge
  const d = X[0]!.length;
  let w = new Array<number>(d).fill(0);
  let lastMaxDelta = Infinity;
  for (let iter = 0; iter < maxIter; iter++) {
    // Gradient g (d) and Hessian H (d×d).
    const g = new Array<number>(d).fill(0);
    const H: number[][] = Array.from({ length: d }, () => new Array<number>(d).fill(0));
    for (let i = 0; i < n; i++) {
      const xi = X[i]!;
      let z = 0;
      for (let k = 0; k < d; k++) z += w[k]! * xi[k]!;
      const p = sigmoid(z);
      const err = p - t[i]!;
      const wgt = Math.max(p * (1 - p), 1e-9); // floor keeps H invertible under separation
      for (let a = 0; a < d; a++) {
        g[a] = g[a]! + err * xi[a]!;
        for (let bcol = 0; bcol < d; bcol++) H[a]![bcol] = H[a]![bcol]! + wgt * xi[a]! * xi[bcol]!;
      }
    }
    // Ridge on non-intercept coefficients (intercept = last column, all-ones).
    for (let a = 0; a < d - 1; a++) {
      g[a] = g[a]! + lambda * w[a]!;
      H[a]![a] = H[a]![a]! + lambda;
    }
    const step = solveLinear(H, g);
    if (!step) return null; // singular normal equations — refuse rather than guess
    // Damping: scale the whole step down when its largest component exceeds MAX_STEP.
    let stepMax = 0;
    for (let a = 0; a < d; a++) stepMax = Math.max(stepMax, Math.abs(step[a]!));
    const damp = stepMax > MAX_STEP ? MAX_STEP / stepMax : 1;
    for (let a = 0; a < d; a++) w[a] = w[a]! - damp * step[a]!;
    if (!w.every((v) => Number.isFinite(v))) return null;
    lastMaxDelta = stepMax * damp;
    if (lastMaxDelta < tol) break;
  }
  if (lastMaxDelta > CONVERGED_TOL) return null; // unconverged (e.g. separation) — refuse
  // Saturation refusal: on (near-)separated data the damped walk can "converge"
  // numerically at a huge-coefficient step function (the gradient dies into the
  // 1e-9 Hessian floor). No genuine probability-calibration relationship needs
  // slopes anywhere near this scale — |w| beyond MAX_COEF is separation, not fit.
  const MAX_COEF = 50;
  for (const v of w) if (Math.abs(v) > MAX_COEF) return null;
  return w;
}

// ============================================================
// Common calibrator-fit shape (so the selector can compare families)
// ============================================================

export type CalibrationMethod = "isotonic" | "platt" | "beta";

export interface CalibratorFit {
  readonly method: CalibrationMethod;
  /** Map a forecast probability in [0,1] to a calibrated probability in [0,1]. */
  readonly predict: (p: number) => number;
  /**
   * Canonical, stable serialization of THIS map's parameters — the honest input
   * to a calibration-commitment (two fits with the same params serialize
   * identically; a changed map changes the string, hence the commitment).
   */
  readonly paramsCanonical: string;
}

// ============================================================
// Platt scaling  —  sigmoid(A·logit(p) + B)
// ============================================================

export interface PlattModel extends CalibratorFit {
  readonly method: "platt";
  readonly a: number;
  readonly b: number;
}

/**
 * Platt scaling on the forecast log-odds. Uses Platt's (1999) target smoothing —
 * y+ = (N+ +1)/(N+ +2), y- = 1/(N- +2) — to prevent the fit from chasing 0/1
 * targets under separation. A 2-parameter, smooth, monotone-when-A≥0 recalibrator;
 * the low-variance alternative to isotonic when settled samples are few.
 */
export function plattScaling(samples: readonly CalibrationSample[]): PlattModel | null {
  const n = samples.length;
  if (n < 2) return null;
  let nPos = 0;
  for (const s of samples) if (s.y === 1) nPos += 1;
  const nNeg = n - nPos;
  if (nPos === 0 || nNeg === 0) return null; // degenerate: cannot fit a slope
  const tPos = (nPos + 1) / (nPos + 2);
  const tNeg = 1 / (nNeg + 2);
  const X: number[][] = samples.map((s) => [logit(s.p), 1]);
  const t: number[] = samples.map((s) => (s.y === 1 ? tPos : tNeg));
  const w = fitLogisticIRLS(X, t);
  if (!w || !Number.isFinite(w[0]!) || !Number.isFinite(w[1]!)) return null;
  const a = w[0]!;
  const b = w[1]!;
  const predict = (p: number): number => clamp01(sigmoid(a * logit(p) + b));
  return {
    method: "platt",
    a: round(a),
    b: round(b),
    predict,
    paramsCanonical: `platt:a=${round(a)}|b=${round(b)}`,
  };
}

// ============================================================
// Beta calibration  —  sigmoid(a·ln p − b·ln(1−p) + c),  a,b ≥ 0
// ============================================================

export interface BetaModel extends CalibratorFit {
  readonly method: "beta";
  readonly a: number;
  readonly b: number;
  readonly c: number;
}

/**
 * Beta calibration (Kull et al. 2017): a 3-parameter map that subsumes the
 * identity and is more flexible than Platt for binary forecasts (it can bend the
 * curve near both 0 and 1 independently). Fit as logistic regression on features
 * [ln p, −ln(1−p), 1]. Monotonicity requires a,b ≥ 0: a single violating
 * coefficient triggers a drop-that-feature refit (per Kull 2017 / the betacal
 * reference implementation); if the REFIT coefficient is itself negative — a
 * genuinely non-monotone forecast/outcome relationship, e.g. a flat-then-
 * decreasing truth (hostile-review construction) — we fall back to the
 * intercept-only base-rate map instead of returning a decreasing "calibration".
 * (The both-negative and refit-negative fallbacks are OUR conservative
 * extension, not part of Kull's prescription.)
 */
export function betaCalibration(samples: readonly CalibrationSample[]): BetaModel | null {
  const n = samples.length;
  if (n < 3) return null;
  let nPos = 0;
  for (const s of samples) if (s.y === 1) nPos += 1;
  if (nPos === 0 || nPos === n) return null;
  const t: number[] = samples.map((s) => s.y);
  const s1 = samples.map((s) => Math.log(clampUnit(s.p))); // ln p
  const s2 = samples.map((s) => -Math.log(1 - clampUnit(s.p))); // −ln(1−p)

  // Intercept-only fallback: the base-rate map (monotone-trivially, never wrong-signed).
  const interceptOnly = (): [number, number, number] => {
    const baseRate = clampUnit(nPos / n);
    return [0, 0, Math.log(baseRate / (1 - baseRate))];
  };

  // Full 3-feature fit: coeffs [a, b, c].
  const Xfull: number[][] = samples.map((_, i) => [s1[i]!, s2[i]!, 1]);
  const wf = fitLogisticIRLS(Xfull, t);
  if (!wf) return null;
  let a = wf[0]!;
  let b = wf[1]!;
  let c = wf[2]!;

  // Enforce a,b ≥ 0. Any refit whose surviving coefficient is ALSO negative
  // collapses to the intercept-only map (never return a decreasing map).
  if (a < 0 && b < 0) {
    [a, b, c] = interceptOnly();
  } else if (a < 0) {
    const wr = fitLogisticIRLS(samples.map((_, i) => [s2[i]!, 1]), t);
    if (!wr) return null;
    [a, b, c] = wr[0]! < 0 ? interceptOnly() : [0, wr[0]!, wr[1]!];
  } else if (b < 0) {
    const wr = fitLogisticIRLS(samples.map((_, i) => [s1[i]!, 1]), t);
    if (!wr) return null;
    [a, b, c] = wr[0]! < 0 ? interceptOnly() : [wr[0]!, 0, wr[1]!];
  }
  if (![a, b, c].every(Number.isFinite)) return null;

  const predict = (p: number): number => {
    const cp = clampUnit(p);
    return clamp01(sigmoid(a * Math.log(cp) + b * -Math.log(1 - cp) + c));
  };
  return {
    method: "beta",
    a: round(a),
    b: round(b),
    c: round(c),
    predict,
    paramsCanonical: `beta:a=${round(a)}|b=${round(b)}|c=${round(c)}`,
  };
}

// ============================================================
// Isotonic wrapped in the common fit shape (composes existing tested code)
// ============================================================

function isotonicFit(samples: readonly CalibrationSample[]): CalibratorFit | null {
  if (samples.length < 2) return null;
  const model = isotonicCalibration(samples);
  if (model.points.length === 0) return null;
  const params = model.points.map((pt) => `${round(pt.x)}:${round(pt.calibrated)}`).join(",");
  return {
    method: "isotonic",
    predict: model.predict,
    paramsCanonical: `isotonic:${params}`,
  };
}

// ============================================================
// Equal-mass ECE (robust on small held-out folds)
// ============================================================

/**
 * ECE over `bins` EQUAL-MASS bins (each bin holds ≈ n/bins samples), the more
 * stable partner to the equal-width ECE in probability-calibration.ts when data is
 * sparse or clustered — an equal-width bin can be empty or hold a single point in
 * the tails and inject noise. Used for out-of-sample model selection below, and
 * exported because it is independently useful.
 *
 * ORDER-INVARIANT BY CONSTRUCTION (hostile-review fix): identical forecasts are
 * pre-pooled into one weighted group (same phase-1 as isotonicCalibration) and a
 * tie group is NEVER split across a bin boundary — a stable sort otherwise leaks
 * the caller's input order into the estimate whenever forecasts tie (the norm for
 * quantized odds-derived probabilities), making the same multiset score
 * differently across orderings. Bins are closed greedily at the ≈n/k cumulative-
 * mass targets over whole groups.
 *
 * SMALL-SAMPLE FLOOR: k is capped so each bin averages ≥ MIN_PER_BIN samples —
 * singleton bins degenerate to mean|p−y|, which maximally punishes a sharp,
 * perfectly calibrated forecaster. With very small n this collapses toward k=1
 * (overall |meanForecast − meanOutcome|), the only honest binned statement left.
 */
export function equalMassEce(samples: readonly CalibrationSample[], bins = 10): number {
  const n = samples.length;
  if (n === 0) return 0;
  const MIN_PER_BIN = 5;
  // Phase 1 — pool identical forecasts into weighted groups (order-invariant).
  const sorted = [...samples].sort((a, b) => a.p - b.p);
  type Group = { p: number; weight: number; ySum: number };
  const groups: Group[] = [];
  for (const s of sorted) {
    const last = groups[groups.length - 1];
    if (last && last.p === s.p) {
      last.weight += 1;
      last.ySum += s.y;
    } else {
      groups.push({ p: s.p, weight: 1, ySum: s.y });
    }
  }
  const k = Math.max(1, Math.min(bins, groups.length, Math.floor(n / MIN_PER_BIN) || 1));
  // Phase 2 — greedy whole-group bins closed at cumulative-mass targets.
  let ece = 0;
  let g = 0;
  let filled = 0;
  for (let bin = 0; bin < k && g < groups.length; bin++) {
    const target = Math.floor(((bin + 1) * n) / k);
    let weight = 0;
    let fSum = 0;
    let ySum = 0;
    // Always take at least one group; keep taking whole groups until the
    // cumulative count reaches this bin's target (last bin sweeps the rest).
    while (g < groups.length && (weight === 0 || filled + weight < target || bin === k - 1)) {
      const grp = groups[g]!;
      weight += grp.weight;
      fSum += grp.p * grp.weight;
      ySum += grp.ySum;
      g += 1;
      if (bin === k - 1 && g >= groups.length) break;
    }
    filled += weight;
    if (weight > 0) ece += (weight / n) * Math.abs(fSum / weight - ySum / weight);
  }
  return round(ece, 6);
}

// ============================================================
// Cross-validated calibrator selection (the honest "which map")
// ============================================================

export interface CalibratorScore {
  readonly method: CalibrationMethod;
  /** Mean out-of-fold equal-mass ECE (lower is better). null if the family could not fit. */
  readonly oofEce: number | null;
}

export interface CalibratorSelection {
  /** The family with the lowest OOF ECE, or "identity" when none beats the raw forecasts. */
  readonly recommended: CalibrationMethod | "identity";
  /** Per-family out-of-fold ECE table (the evidence behind the choice). */
  readonly scores: readonly CalibratorScore[];
  /** OOF equal-mass ECE of the RAW (uncalibrated) forecasts — the bar to beat. */
  readonly rawOofEce: number;
  /**
   * The noise bar: the 90th percentile of the best-family ECE "gain" observed on
   * `nullSims` parametric-bootstrap replicas where the raw forecasts are TRUE
   * (y ~ Bernoulli(p)). A real family must beat raw by MORE than this (and than
   * minEceGain) — otherwise its win is indistinguishable from selection noise.
   */
  readonly nullGainMargin: number;
  /**
   * The recommended family, refit on ALL data. Null whenever `recommended` is
   * "identity". Callers MUST still null-check `model` even when `recommended`
   * names a family: the all-data refit can (near-unreachably) refuse — a family
   * that fit every training fold almost always fits their union, but it is not
   * guaranteed — leaving `recommended` set to the OOF winner while `model` is
   * null. Treat a null `model` as "apply nothing" regardless of `recommended`.
   */
  readonly model: CalibratorFit | null;
  readonly sampleSize: number;
  readonly folds: number;
  readonly seed: number;
}

const FAMILIES: readonly CalibrationMethod[] = ["isotonic", "platt", "beta"];

function fitFamily(method: CalibrationMethod, samples: readonly CalibrationSample[]): CalibratorFit | null {
  switch (method) {
    case "isotonic":
      return isotonicFit(samples);
    case "platt":
      return plattScaling(samples);
    case "beta":
      return betaCalibration(samples);
  }
}

/**
 * One full CV pass: per-family pooled out-of-fold ECE + the raw bar.
 * Shared by the real-data selection and the parametric-bootstrap null below.
 */
function crossValidatedScores(
  samples: readonly CalibrationSample[],
  folds: number,
  seed: number,
  bins: number,
): { rawOofEce: number; scores: CalibratorScore[] } {
  const n = samples.length;
  const perm = seededPermutation(n, seed);
  const foldOf = new Array<number>(n);
  for (let rank = 0; rank < n; rank++) foldOf[perm[rank]!] = rank % folds;

  // Raw (identity) out-of-fold ECE: for the identity map the held-out prediction
  // IS the raw forecast, so pooling held-out raw samples across folds is the whole
  // sample — and equalMassEce is order-invariant (tie pre-pooling), so scoring the
  // sample once is EXACTLY the pooled-fold score, not merely approximately.
  const rawOofEce = equalMassEce(samples, bins);

  const scores: CalibratorScore[] = FAMILIES.map((method) => {
    const pooled: CalibrationSample[] = [];
    let anyFoldFailed = false;
    for (let f = 0; f < folds; f++) {
      const train: CalibrationSample[] = [];
      const test: CalibrationSample[] = [];
      for (let i = 0; i < n; i++) (foldOf[i] === f ? test : train).push(samples[i]!);
      if (test.length === 0) continue;
      const fit = fitFamily(method, train);
      if (!fit) {
        anyFoldFailed = true;
        break;
      }
      for (const s of test) pooled.push({ p: clamp01(fit.predict(s.p)), y: s.y });
    }
    if (anyFoldFailed || pooled.length === 0) return { method, oofEce: null };
    return { method, oofEce: equalMassEce(pooled, bins) };
  });
  return { rawOofEce, scores };
}

function bestGain(rawOofEce: number, scores: readonly CalibratorScore[]): { best: CalibratorScore | null; gain: number } {
  let best: CalibratorScore | null = null;
  for (const s of scores) {
    if (s.oofEce === null) continue;
    if (best === null || s.oofEce < best.oofEce!) best = s;
  }
  return { best, gain: best ? rawOofEce - best.oofEce! : 0 };
}

/**
 * Choose a calibrator family by k-fold, OUT-OF-SAMPLE ECE — the honest fix for
 * "isotonic by fiat". For each family we fit on the training folds and score the
 * held-out fold, so an overfit map is penalized where it actually matters (data it
 * did not see). The winner is refit on all data. If no family beats the raw
 * forecasts' OOF ECE, we recommend "identity" (apply nothing).
 *
 * THE NOISE BAR (hostile-review fix): finite-sample binned ECE is biased upward
 * more for dispersed raw forecasts than for the compressed predictions a fitted
 * map produces, so at a zero margin a map "wins" on PERFECTLY calibrated data
 * most of the time (measured 70–88% across n=40..200 before this fix). The
 * selection therefore calibrates its own bar: `nullSims` parametric-bootstrap
 * replicas redraw y ~ Bernoulli(p) — the world where raw is TRUE — run the
 * identical CV pipeline, and record the best-family "gain" that pure selection
 * noise produces. The real gain must exceed the 90th percentile of those null
 * gains (and any explicit minEceGain). No invented constant: the bar is measured
 * from the caller's own forecast distribution at the caller's own n.
 *
 * Returns null below a floor where CV is not meaningful. Fully deterministic given
 * `seed` (fold shuffle + null replica outcomes).
 */
export function selectCalibrator(
  samples: readonly CalibrationSample[],
  opts: {
    readonly folds?: number;
    readonly seed?: number;
    readonly bins?: number;
    readonly minSample?: number;
    /** Extra absolute OOF-ECE improvement required ON TOP of the measured noise bar. Default 0. */
    readonly minEceGain?: number;
    /**
     * Parametric-bootstrap replicas used to measure the noise bar. Default 16.
     * 0 disables the noise bar (raw comparison only — the pre-fix behavior; use
     * only in tests or when the caller supplies its own minEceGain).
     */
    readonly nullSims?: number;
  } = {},
): CalibratorSelection | null {
  const folds = opts.folds ?? 5;
  const seed = opts.seed ?? 0x5eed;
  const bins = opts.bins ?? 10;
  const minSample = opts.minSample ?? 40;
  const minEceGain = opts.minEceGain ?? 0;
  const nullSims = opts.nullSims ?? 16;
  const n = samples.length;
  if (!Number.isInteger(folds) || folds < 2) return null; // folds=0 → NaN fold ids; fractional folds silently drop samples
  if (!Number.isInteger(nullSims) || nullSims < 0) return null;
  if (n < Math.max(minSample, 2 * folds)) return null;
  if (!samples.every((s) => Number.isFinite(s.p) && (s.y === 0 || s.y === 1))) return null;

  const { rawOofEce, scores } = crossValidatedScores(samples, folds, seed, bins);
  const { best, gain } = bestGain(rawOofEce, scores);

  // Noise bar: what "gain" does the best family show when raw is TRUE?
  let nullGainMargin = 0;
  if (nullSims > 0) {
    const gains: number[] = [];
    for (let b = 0; b < nullSims; b++) {
      const rand = mulberry32((seed ^ 0x9e3779b9) + 7919 * (b + 1));
      const replica: CalibrationSample[] = samples.map((s) => ({ p: s.p, y: rand() < s.p ? 1 : 0 }));
      const cv = crossValidatedScores(replica, folds, seed, bins);
      gains.push(Math.max(0, bestGain(cv.rawOofEce, cv.scores).gain));
    }
    gains.sort((a, b2) => a - b2);
    nullGainMargin = gains[Math.min(gains.length - 1, Math.ceil(0.9 * gains.length) - 1)] ?? 0;
  }

  const requiredGain = Math.max(minEceGain, nullGainMargin);
  const beatsRaw = best !== null && gain > requiredGain;
  // A winning family is refit on ALL data. That full-sample refit succeeds in
  // practice — the winner fit every training fold, so it almost always fits their
  // union — but it is not guaranteed, so `model` can be null even when beatsRaw is
  // true. `recommended` still names the OOF winner in that case; consumers gate on
  // `model` (see its field doc), treating a null model as "apply nothing".
  const recommended: CalibrationMethod | "identity" = beatsRaw ? best!.method : "identity";
  const model = beatsRaw ? fitFamily(best!.method, samples) : null;

  return { recommended, scores, rawOofEce, nullGainMargin, model, sampleSize: n, folds, seed };
}

/**
 * Performance confidence intervals for CONTINUOUS returns (ROI, units, average
 * edge) — the honest counterpart to the Wilson interval, which only covers
 * binomial proportions (win rate, beat-close rate).
 *
 * Win rate is a proportion -> Wilson (model-limitations.ts). ROI / units / P&L
 * is a MEAN OF SKEWED CONTINUOUS returns -> the normal approximation lies (a few
 * big winners skew it) and Wilson does not apply. The right tool is the
 * BOOTSTRAP, and for small, skewed sports samples the bias-corrected and
 * accelerated (BCa) bootstrap (Efron & Tibshirani 1993) has the best coverage.
 *
 * Two design commitments make this fit GSE's trust doctrine, not just its math:
 *  1. DETERMINISTIC. A public performance claim's uncertainty band must be
 *     reproducible by anyone from the same sealed ledger, or it is not
 *     verifiable. The bootstrap RNG is seeded; the same returns + seed always
 *     yield the identical interval, so the CI itself can live in the receipt.
 *  2. HONEST BY CONSTRUCTION. The interval is reported next to the point
 *     estimate so a skeptic sees the uncertainty, never a falsely precise ROI.
 *
 * Pure, dependency-free, no I/O. The jackknife influence for a mean is exact
 * and O(n) (no optimization machinery needed — the trust-region/Newton solvers
 * some references reach for are irrelevant to a mean; they only matter for
 * fitting complex M-estimators, which a performance ledger does not do).
 */

export type CiMethod = "percentile" | "bca" | "studentized" | "empirical-bernstein";

export interface PerformanceCi {
  readonly point: number; // observed mean (ROI / units per bet)
  readonly low: number;
  readonly high: number;
  readonly alpha: number; // e.g. 0.05 for a 95% interval
  readonly n: number;
  readonly resamples: number;
  readonly seed: number; // fixed -> the interval is reproducible/auditable
  readonly method: CiMethod;
  /** BCa bias-correction z0 and acceleration a (0 for the percentile method). */
  readonly z0: number;
  readonly acceleration: number;
  /**
   * Studentized bootstrap-t pivot quantiles and the plug-in standard error, when
   * method === "studentized". A receipt can carry these so a skeptic re-derives
   * the interval as point - tHigh*se .. point - tLow*se (the inversion). Absent
   * for percentile/BCa. NOTE: on heavily lopsided ledgers a bound can be
   * +/-Infinity — the honest "bootstrap-t cannot bound this side from this
   * ledger" answer (see degenerateResamples).
   */
  readonly tLow?: number;
  readonly tHigh?: number;
  readonly standardError?: number;
  /**
   * Count of degenerate resamples (all draws identical -> se* = 0). These are a
   * CENSORED TAIL of the pivot distribution, not noise: an all-modal-value
   * resample puts theta* at an extreme with se* = 0, i.e. the pivot is properly
   * +/-Infinity. They are assigned signed infinite pivots so a heavy degenerate
   * fraction honestly widens (or unbounds) the interval instead of silently
   * narrowing it. Disclosed on the receipt so a skeptic sees the regime.
   */
  readonly degenerateResamples?: number;
  /**
   * Skewness (Fisher-Pearson g1) of the studentized pivot distribution t*
   * itself — a DIAGNOSTIC, not a certification. Near 0 = the pivot is close to
   * symmetric, the regime where the second-order theory motivating bootstrap-t
   * applies most cleanly; large magnitude = the quantile inversion leans on a
   * skewed pivot and the second-order-accuracy claim is weaker for this ledger.
   * It does NOT mean the interval is wrong (BCa and empirical-Bernstein remain
   * valid cross-checks), and no pass/fail threshold is asserted. ABSENT
   * (undefined) whenever any degenerate (infinite) pivots exist — a skewness
   * computed over only the finite subset would silently drop exactly the
   * asymmetric tail being diagnosed, overclaiming symmetry precisely where the
   * pivot is least trustworthy (the same bug class as imputing t*=0, fixed in
   * this file once already).
   */
  readonly tStarSkewness?: number;
}

/** Deterministic PRNG (mulberry32) — seeded so the interval is reproducible. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function mean(xs: readonly number[]): number {
  let s = 0;
  for (const x of xs) s += x;
  return s / xs.length;
}

/**
 * Linear-interpolated percentile of a SORTED array; p in [0,1]. Convention:
 * Hyndman-Fan type 7 (numpy default, R type 7) — idx = p*(n-1) with linear
 * interpolation between adjacent order statistics. Equal neighbors (including
 * equal infinities) short-circuit so interpolation never produces Inf-Inf NaNs.
 */
function sortedPercentile(sorted: readonly number[], p: number): number {
  if (sorted.length === 1) return sorted[0]!;
  const idx = p * (sorted.length - 1);
  const lo = Math.floor(idx);
  const hi = Math.ceil(idx);
  if (lo === hi) return sorted[lo]!;
  // Equal neighbors (ties, or two same-sign infinities): interpolation would be
  // a no-op or an Inf-Inf NaN — return the shared value directly.
  if (sorted[lo]! === sorted[hi]!) return sorted[lo]!;
  // Infinite endpoint adjacent to a finite (or opposite-sign infinite) neighbor:
  // linear interpolation computes (±Inf) + frac·(±Inf) = NaN, which silently
  // destroys the honest unbounded-tail semantics (a NaN bound reads as a false
  // "cannot cover" downstream). Snap to the infinite endpoint so a boundary
  // straddle yields an honestly unbounded quantile instead of NaN. Finite/finite
  // pairs fall through to exact interpolation, unchanged.
  if (!Number.isFinite(sorted[lo]!)) return sorted[lo]!;
  if (!Number.isFinite(sorted[hi]!)) return sorted[hi]!;
  return sorted[lo]! + (idx - lo) * (sorted[hi]! - sorted[lo]!);
}

/**
 * Comparator safe for +/-Infinity: (a, b) => a - b returns NaN for two
 * same-sign infinities, which is unspecified behavior for Array#sort.
 */
function ascending(a: number, b: number): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

/**
 * Sample skewness, Fisher-Pearson g1 = m3 / m2^1.5 (moment estimator). The
 * bias-corrected G1 variant differs by sqrt(n(n-1))/(n-2), within ~1e-4 of 1 at
 * the resample counts used here (thousands), so g1 is preferred as the simplest
 * formula a skeptic can reproduce by hand from the receipt. Returns 0 for a
 * zero-variance sample (skewness of a constant is undefined; 0 is the honest
 * "no asymmetry evidence" answer for a degenerate spread).
 */
function sampleSkewness(xs: readonly number[]): number {
  const n = xs.length;
  // n<3 or zero spread: skewness is UNDEFINED, not zero — returning 0 would
  // read as "evidence of symmetry" from a sample that cannot evidence
  // anything (hostile-review fix). NaN here maps to an absent field upstream.
  if (n < 3) return NaN;
  const m = mean(xs);
  let m2 = 0;
  let m3 = 0;
  for (const x of xs) {
    const d = x - m;
    m2 += d * d;
    m3 += d * d * d;
  }
  m2 /= n;
  m3 /= n;
  if (!(m2 > 0)) return NaN;
  return m3 / Math.pow(m2, 1.5);
}

/** Shared option validation: bad resamples/alpha -> the CI is refused (null). */
function validCiOptions(alpha: number, resamples: number): boolean {
  return Number.isInteger(resamples) && resamples >= 1 && alpha > 0 && alpha < 1;
}

/** Error function via Abramowitz-Stegun 7.1.26 (|err| < 1.5e-7). */
function erf(x: number): number {
  const sign = x >= 0 ? 1 : -1;
  const ax = Math.abs(x);
  const t = 1 / (1 + 0.3275911 * ax);
  const y =
    1 -
    (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t + 0.254829592) *
      t *
      Math.exp(-ax * ax);
  return sign * y;
}

/** Standard-normal CDF, Phi(x) = 0.5 (1 + erf(x/sqrt2)). */
export function normalCdf(x: number): number {
  return 0.5 * (1 + erf(x / Math.SQRT2));
}

/** Inverse standard-normal CDF (Acklam), |err| < 1.2e-9. */
export function normalQuantile(p: number): number {
  if (p <= 0 || p >= 1) throw new Error("normalQuantile: p in (0,1)");
  const a = [-3.969683028665376e1, 2.209460984245205e2, -2.759285104469687e2, 1.38357751867269e2, -3.066479806614716e1, 2.506628277459239];
  const b = [-5.447609879822406e1, 1.615858368580409e2, -1.556989798598866e2, 6.680131188771972e1, -1.328068155288572e1];
  const c = [-7.784894002430293e-3, -3.223964580411365e-1, -2.400758277161838, -2.549732539343734, 4.374664141464968, 2.938163982698783];
  const d = [7.784695709041462e-3, 3.224671290700398e-1, 2.445134137142996, 3.754408661907416];
  const pLow = 0.02425;
  if (p < pLow) {
    const q = Math.sqrt(-2 * Math.log(p));
    return (((((c[0]! * q + c[1]!) * q + c[2]!) * q + c[3]!) * q + c[4]!) * q + c[5]!) /
      (((((d[0]! * q + d[1]!) * q + d[2]!) * q + d[3]!) * q + 1));
  }
  if (p <= 1 - pLow) {
    const q = p - 0.5;
    const r = q * q;
    return (((((a[0]! * r + a[1]!) * r + a[2]!) * r + a[3]!) * r + a[4]!) * r + a[5]!) * q /
      (((((b[0]! * r + b[1]!) * r + b[2]!) * r + b[3]!) * r + b[4]!) * r + 1);
  }
  const q = Math.sqrt(-2 * Math.log(1 - p));
  return -(((((c[0]! * q + c[1]!) * q + c[2]!) * q + c[3]!) * q + c[4]!) * q + c[5]!) /
    (((((d[0]! * q + d[1]!) * q + d[2]!) * q + d[3]!) * q + 1));
}

/**
 * A statistic of a sample: the mean (ROI/units) is the common case, but this is
 * deliberately general. A CONFOUND-ADJUSTED edge — a regression coefficient of
 * outcome on signal after controlling for game volatility/strength — is also a
 * Statistic, and it plugs straight in.
 *
 * NOTE: this file ships NO optimizer. It only computes the injected statistic
 * (the mean, exactly) and its delete-one jackknife. When the injected statistic
 * is itself an expensive M-estimator fit on ill-conditioned data, the FITTING
 * (Newton with Levenberg-Marquardt / dogleg / Steihaug-CG safeguards, and
 * Hessian-based influence for scale) belongs in the caller / a future module —
 * it is a documented roadmap, not code that lives here.
 */
export type Statistic = (sample: readonly number[]) => number;

export const meanStatistic: Statistic = mean;

function bootstrapStatistic(
  data: readonly number[],
  statistic: Statistic,
  resamples: number,
  seed: number,
): number[] {
  const rng = mulberry32(seed);
  const n = data.length;
  const reps = new Array<number>(resamples);
  const sample = new Array<number>(n);
  for (let b = 0; b < resamples; b++) {
    for (let i = 0; i < n; i++) sample[i] = data[Math.floor(rng() * n)]!;
    reps[b] = statistic(sample);
  }
  reps.sort((x, y) => x - y);
  return reps;
}

/**
 * General bias-corrected & accelerated (BCa) bootstrap CI for ANY statistic of
 * `data` (Efron & Tibshirani 1993). The mean is the common case (bcaMeanCi); a
 * confound-adjusted edge estimate is the reason this is general. Delete-one
 * jackknife computes the acceleration exactly for any statistic. Falls back to a
 * point interval on zero variance; null on too-little / non-finite data.
 */
export function bcaCi(
  data: readonly number[],
  statistic: Statistic,
  opts: { alpha?: number; resamples?: number; seed?: number } = {},
): PerformanceCi | null {
  const alpha = opts.alpha ?? 0.05;
  const resamples = opts.resamples ?? 10000;
  const seed = opts.seed ?? 20260702; // FIXED default -> reproducible/auditable
  const n = data.length;
  if (n < 2 || !data.every(Number.isFinite) || !validCiOptions(alpha, resamples)) return null;

  const point = statistic(data);
  const reps = bootstrapStatistic(data, statistic, resamples, seed);

  // Zero-variance resample distribution: the honest CI is a point.
  if (reps[0] === reps[reps.length - 1]) {
    return { point, low: point, high: point, alpha, n, resamples, seed, method: "bca", z0: 0, acceleration: 0 };
  }

  // Bias correction z0 = Phi^-1( P(theta* <= theta_hat) ), with the MID-P tie
  // correction (below + equal/2): sports ledgers are near-two-point discrete, so
  // a non-trivial mass of replicates EQUALS the point exactly; counting ties as
  // wholly "not below" (strict <) biases z0 negative and drags both bounds down.
  let below = 0;
  let equal = 0;
  for (const r of reps) {
    if (r < point) below++;
    else if (r === point) equal++;
  }
  const frac = Math.min(1 - 1e-9, Math.max(1e-9, (below + 0.5 * equal) / resamples));
  const z0 = normalQuantile(frac);

  // Acceleration a from delete-one jackknife influence (exact for any statistic).
  const jack = new Array<number>(n);
  const without = new Array<number>(n - 1);
  for (let i = 0; i < n; i++) {
    let k = 0;
    for (let j = 0; j < n; j++) if (j !== i) without[k++] = data[j]!;
    jack[i] = statistic(without);
  }
  const jackMean = mean(jack);
  let s2 = 0;
  let s3 = 0;
  for (const jm of jack) {
    const u = (n - 1) * (jackMean - jm);
    s2 += u * u;
    s3 += u * u * u;
  }
  const acceleration = s2 > 0 ? s3 / (6 * Math.pow(s2, 1.5)) : 0;

  const adjust = (z: number): number => {
    const num = z0 + z;
    const denom = 1 - acceleration * num;
    if (Math.abs(denom) < 1e-9) return normalCdf(z0); // degenerate -> fall toward median
    return normalCdf(z0 + num / denom);
  };
  const aLo = Math.min(1 - 1e-9, Math.max(1e-9, adjust(normalQuantile(alpha / 2))));
  const aHi = Math.min(1 - 1e-9, Math.max(1e-9, adjust(normalQuantile(1 - alpha / 2))));

  return {
    point,
    low: sortedPercentile(reps, aLo),
    high: sortedPercentile(reps, aHi),
    alpha,
    n,
    resamples,
    seed,
    method: "bca",
    z0,
    acceleration,
  };
}

/** General percentile bootstrap CI — the un-corrected baseline for any statistic. */
export function percentileCi(
  data: readonly number[],
  statistic: Statistic,
  opts: { alpha?: number; resamples?: number; seed?: number } = {},
): PerformanceCi | null {
  const alpha = opts.alpha ?? 0.05;
  const resamples = opts.resamples ?? 10000;
  const seed = opts.seed ?? 20260702;
  const n = data.length;
  if (n < 2 || !data.every(Number.isFinite) || !validCiOptions(alpha, resamples)) return null;
  const reps = bootstrapStatistic(data, statistic, resamples, seed);
  return {
    point: statistic(data),
    low: sortedPercentile(reps, alpha / 2),
    high: sortedPercentile(reps, 1 - alpha / 2),
    alpha,
    n,
    resamples,
    seed,
    method: "percentile",
    z0: 0,
    acceleration: 0,
  };
}

/** BCa CI for the MEAN (ROI/units per bet) — the common ledger case. */
export function bcaMeanCi(
  returns: readonly number[],
  opts: { alpha?: number; resamples?: number; seed?: number } = {},
): PerformanceCi | null {
  return bcaCi(returns, meanStatistic, opts);
}

/** Percentile CI for the MEAN — the un-corrected baseline. */
export function percentileMeanCi(
  returns: readonly number[],
  opts: { alpha?: number; resamples?: number; seed?: number } = {},
): PerformanceCi | null {
  return percentileCi(returns, meanStatistic, opts);
}

/**
 * Delete-one jackknife standard error of a statistic — the exact, O(n),
 * dependency-free plug-in SE. For the mean it equals s/sqrt(n); for a general
 * statistic it is the standard nonparametric SE estimate. This is the default
 * per-replicate SE used by the studentized bootstrap.
 */
export function jackknifeStandardError(sample: readonly number[], statistic: Statistic): number {
  const n = sample.length;
  if (n < 2) return 0;
  const jack = new Array<number>(n);
  const without = new Array<number>(n - 1);
  for (let i = 0; i < n; i++) {
    let k = 0;
    for (let j = 0; j < n; j++) if (j !== i) without[k++] = sample[j]!;
    jack[i] = statistic(without);
  }
  const jm = mean(jack);
  let s2 = 0;
  for (const j of jack) s2 += (j - jm) * (j - jm);
  return Math.sqrt(((n - 1) / n) * s2);
}

/**
 * STUDENTIZED (bootstrap-t) confidence interval — the second-order-accurate
 * method that INVERTS a pivotal quantity instead of reading quantiles off the
 * statistic's own scale (Efron & Tibshirani 1993 ch.12; Hall 1992). For each
 * resample it forms t* = (theta* - theta_hat) / se*, where se* is the resample's
 * own (jackknife) standard error, then inverts:
 *
 *     CI = [ theta_hat - t*_{1-a/2}·se_hat ,  theta_hat - t*_{a/2}·se_hat ]
 *
 * Note the TAIL REVERSAL — this is the inversion, not a bug. On right-skewed
 * data (a few big winners, the sports-ROI case) the studentized pivot's LOWER
 * tail is heavier, which stretches the interval's UPPER edge outward and gives
 * coverage measurably closer to nominal than the percentile method. Verified by
 * Monte-Carlo in the test suite (studentizedMeanCi covers a skewed true mean at
 * ~nominal, ahead of percentile).
 *
 * Why it belongs here: ROI/units per bet is a mean of skewed continuous returns
 * whose analytic SE is CHEAP and reliable (jackknife = s/sqrt(n), exact). The
 * literature's own rule is "studentize when a good SE estimator is available" —
 * which is exactly this case. Deterministic/seeded like BCa, so a public band
 * reproduces from the sealed ledger.
 *
 * The per-replicate SE is injectable (defaults to the jackknife) so a caller
 * with an analytic SE for a complex statistic can supply it. Returns null on
 * too-little / non-finite data; a point interval on zero variance.
 */
export function studentizedCi(
  data: readonly number[],
  statistic: Statistic,
  opts: {
    alpha?: number;
    resamples?: number;
    seed?: number;
    standardError?: (sample: readonly number[]) => number;
  } = {},
): PerformanceCi | null {
  const alpha = opts.alpha ?? 0.05;
  const resamples = opts.resamples ?? 10000;
  const seed = opts.seed ?? 20260702;
  const n = data.length;
  if (n < 2 || !data.every(Number.isFinite) || !validCiOptions(alpha, resamples)) return null;

  const se = opts.standardError ?? ((s: readonly number[]) => jackknifeStandardError(s, statistic));
  const point = statistic(data);
  const seHat = se(data);

  // Degeneracy TOLERANCE, not exact zero: a resample of 25 identical +0.909...
  // returns (a -110 win at 1 unit) has a floating-point-accumulation SD of
  // ~1e-16, not 0 — an exact-zero check would miss it and divide by FP noise,
  // producing an absurd ~1e15 pivot instead of the honest infinity. Any real
  // mixed resample of bet returns has SD orders of magnitude above this.
  const seTol = 1e-9 * (1 + Math.abs(point));

  // Zero variance -> the honest interval is a point (se_hat ~ 0, no pivot).
  if (!(seHat > seTol)) {
    return {
      point, low: point, high: point, alpha, n, resamples, seed,
      method: "studentized", z0: 0, acceleration: 0, tLow: 0, tHigh: 0, standardError: 0,
      degenerateResamples: 0,
    };
  }

  const rng = mulberry32(seed);
  const tStar = new Array<number>(resamples);
  const sample = new Array<number>(n);
  let degenerateResamples = 0;
  for (let b = 0; b < resamples; b++) {
    for (let i = 0; i < n; i++) sample[i] = data[Math.floor(rng() * n)]!;
    const thetaB = statistic(sample);
    const seB = se(sample);
    if (seB > seTol) {
      tStar[b] = (thetaB - point) / seB;
    } else {
      // Degenerate resample (all draws identical -> se* ~ 0). This is NOT
      // information-free: an all-modal-value resample puts theta* at an EXTREME
      // of the resample distribution with zero spread — the pivot is properly
      // +/-Infinity, the heaviest point of one tail. Imputing 0 would teleport
      // that tail to the center and silently narrow the interval (an
      // overconfident published bound on lopsided ledgers). Assign the signed
      // infinity; if enough mass lands in a tail, the corresponding bound is
      // honestly infinite: "bootstrap-t cannot bound this side from this
      // ledger." Only theta* at the point (within tolerance) is null info.
      degenerateResamples++;
      const diff = thetaB - point;
      tStar[b] = Math.abs(diff) <= seTol ? 0 : diff > 0 ? Number.POSITIVE_INFINITY : Number.NEGATIVE_INFINITY;
    }
  }
  tStar.sort(ascending); // (a-b) comparator NaNs on same-sign infinities

  // Pivot-symmetry diagnostic (skewness is order-independent, so computing on
  // the sorted array is identical). Withheld entirely when any infinite pivots
  // exist — see the tStarSkewness field doc for why a finite-subset skewness
  // would be the same silent-overclaim bug class this file already fixed once.
  // Also withheld (NaN -> undefined) when the pivot set is too small or has
  // zero spread — skewness is undefined there, and 0 would overclaim symmetry.
  const rawSkew = degenerateResamples === 0 ? sampleSkewness(tStar) : NaN;
  const tStarSkewness = Number.isFinite(rawSkew) ? rawSkew : undefined;

  // Quantiles of the pivot, then invert (tails reverse).
  const tLow = sortedPercentile(tStar, alpha / 2);
  const tHigh = sortedPercentile(tStar, 1 - alpha / 2);

  return {
    point,
    low: point - tHigh * seHat,
    high: point - tLow * seHat,
    alpha,
    n,
    resamples,
    seed,
    method: "studentized",
    z0: 0,
    acceleration: 0,
    tLow,
    tHigh,
    standardError: seHat,
    degenerateResamples,
    ...(tStarSkewness !== undefined ? { tStarSkewness } : {}),
  };
}

/**
 * Closed-form standard error of the MEAN: s/sqrt(n) (sample sd, (n-1) denom).
 * This is exactly equal to the delete-one jackknife SE of the mean (proven in
 * the test suite) but O(n) instead of O(n^2), which is what keeps the studentized
 * mean interval fast on a large ledger.
 */
export function meanStandardError(sample: readonly number[]): number {
  const n = sample.length;
  if (n < 2) return 0;
  const m = mean(sample);
  let ss = 0;
  for (const x of sample) ss += (x - m) * (x - m);
  return Math.sqrt(ss / (n * (n - 1)));
}

/**
 * Studentized (bootstrap-t) CI for the MEAN (ROI/units per bet). Uses the exact
 * O(n) closed-form SE (s/sqrt(n)) per resample — identical to the jackknife but
 * far cheaper — so this is the cheapest place the method's second-order accuracy
 * is fully earned. The recommended interval for a public ROI band on a small,
 * skewed ledger.
 */
export function studentizedMeanCi(
  returns: readonly number[],
  opts: { alpha?: number; resamples?: number; seed?: number } = {},
): PerformanceCi | null {
  return studentizedCi(returns, meanStatistic, { ...opts, standardError: meanStandardError });
}

/**
 * EMPIRICAL-BERNSTEIN worst-case CI for the MEAN (Maurer & Pontil 2009, thm 4)
 * — the third, NON-BOOTSTRAP leg of the interval stack, and the only one with a
 * FINITE-SAMPLE guarantee (no asymptotics at all).
 *
 * Why it is legitimately applicable to a bet ledger where generic concentration
 * bounds are not: per-bet unit returns are BOUNDED BY CONSTRUCTION — a loss is
 * exactly -1 stake, a win pays decimalOdds-1, both known per pick — so the
 * bounded-support assumption is a fact of the data, not a modeling choice. For
 * i.i.d. X in a range of width R, with probability >= 1-delta:
 *
 *   |mean - mu| <= sqrt(2·s²·ln(2/delta)/n) + 7·R·ln(2/delta)/(3(n-1))
 *
 * (s² the unbiased sample variance; two-sided at alpha uses delta = alpha/2 per
 * side.) The bound is deliberately CONSERVATIVE (wider than BCa/studentized) —
 * that is its role: a profit claim that clears even this band holds under
 * worst-case finite-sample assumptions, with zero resampling and therefore zero
 * Monte-Carlo error. Deterministic by construction (no RNG).
 *
 * `range` defaults to the observed support width of the sealed ledger (the
 * exact support of the record the claim is about); a caller wanting a stricter
 * prior bound (e.g. the max decimal payout offered) can inject it.
 */
export function empiricalBernsteinMeanCi(
  returns: readonly number[],
  opts: { alpha?: number; range?: number } = {},
): PerformanceCi | null {
  const alpha = opts.alpha ?? 0.05;
  const n = returns.length;
  if (n < 2 || !returns.every(Number.isFinite) || !(alpha > 0 && alpha < 1)) return null;

  const point = mean(returns);
  let lo = returns[0]!;
  let hi = returns[0]!;
  let ss = 0;
  for (const x of returns) {
    if (x < lo) lo = x;
    if (x > hi) hi = x;
    ss += (x - point) * (x - point);
  }
  const s2 = ss / (n - 1);
  const range = opts.range ?? hi - lo;
  if (!(range >= 0) || !Number.isFinite(range)) return null;

  // Zero spread -> the honest interval is a point.
  if (range === 0 || s2 === 0) {
    return {
      point, low: point, high: point, alpha, n, resamples: 0, seed: 0,
      method: "empirical-bernstein", z0: 0, acceleration: 0,
    };
  }

  const logTerm = Math.log(4 / alpha); // ln(2/(alpha/2)) per side, two-sided
  const width = Math.sqrt((2 * s2 * logTerm) / n) + (7 * range * logTerm) / (3 * (n - 1));

  return {
    point,
    low: point - width,
    high: point + width,
    alpha,
    n,
    resamples: 0, // no resampling: the bound is closed-form
    seed: 0,
    method: "empirical-bernstein",
    z0: 0,
    acceleration: 0,
  };
}
